// Shared 'Gift Card Redeemed' property shape for the storefront and checkout surfaces; keep it in one place so the warehouse event stays identical across sources.
export function mapGiftCardRedeemedFields({ source, customer_id, store_id }, details = {}) {
    return {
        source,
        customer_id: customer_id ?? null,
        store_id: store_id ?? null,
        code: details.code || '', // Masked in the component (first 4 chars kept), never the raw code.
        status: details.status || '',
        reason: details.reason || null, // Only set on a failed attempt.
        redemption_amount: details.amount ?? null,
        new_balance: details.new_balance ?? null,
        expires_at: details.expires_at ?? null,
    };
}
